L69: static inline u16 mlx5e_calc_min_inline(enum mlx5_inline_modes mode,
L70: 					struct sk_buff *skb)
L71: {
L72: 	u16 hlen;
L73: 	switch (mode) {
L74: 	case MLX5_INLINE_MODE_NONE:
L75: 		return 0;
L76: 	case MLX5_INLINE_MODE_TCP_UDP:
L77: 		hlen = eth_get_headlen(skb->dev, skb->data, skb_headlen(skb));
L78: 		if (hlen == ETH_HLEN && !skb_vlan_tag_present(skb))
L79: 			hlen += VLAN_HLEN;
L80: 		break;
L81: 	case MLX5_INLINE_MODE_IP:
L82: 		hlen = mlx5e_skb_l3_header_offset(skb);
L83: 		break;
L84: 	case MLX5_INLINE_MODE_L2:
L85: 	default:
L86: 		hlen = mlx5e_skb_l2_header_offset(skb);
L87: 	}
L88: 	return min_t(u16, hlen, skb_headlen(skb));
L89: }
