L138: static inline u16
L139: mlx5e_tx_get_gso_ihs(struct mlx5e_txqsq *sq, struct sk_buff *skb, int *hopbyhop)
L140: {
L141: 	struct mlx5e_sq_stats *stats = sq->stats;
L142: 	u16 ihs;
L143: 	*hopbyhop = 0;
L144: 	if (skb->encapsulation) {
L145: 		if (skb_shinfo(skb)->gso_type & SKB_GSO_UDP_L4)
L146: 			ihs = skb_inner_transport_offset(skb) +
L147: 			      sizeof(struct udphdr);
L148: 		else
L149: 			ihs = skb_inner_tcp_all_headers(skb);
L150: 		stats->tso_inner_packets++;
L151: 		stats->tso_inner_bytes += skb->len - ihs;
L152: 	} else {
L153: 		if (skb_shinfo(skb)->gso_type & SKB_GSO_UDP_L4) {
L154: 			ihs = skb_transport_offset(skb) + sizeof(struct udphdr);
L155: 		} else {
L156: 			ihs = skb_tcp_all_headers(skb);
L157: 			if (ipv6_has_hopopt_jumbo(skb)) {
L158: 				*hopbyhop = sizeof(struct hop_jumbo_hdr);
L159: 				ihs -= sizeof(struct hop_jumbo_hdr);
L160: 			}
L161: 		}
L162: 		stats->tso_packets++;
L163: 		stats->tso_bytes += skb->len - ihs - *hopbyhop;
L164: 	}
L165: 	return ihs;
L166: }
