L168: static inline int
L169: mlx5e_txwqe_build_dsegs(struct mlx5e_txqsq *sq, struct sk_buff *skb,
L170: 			unsigned char *skb_data, u16 headlen,
L171: 			struct mlx5_wqe_data_seg *dseg)
L172: {
L173: 	dma_addr_t dma_addr = 0;
L174: 	u8 num_dma          = 0;
L175: 	int i;
L176: 
L177: 	if (headlen) {
L178: 		dma_addr = dma_map_single(sq->pdev, skb_data, headlen,
L179: 					  DMA_TO_DEVICE);
L180: 		if (unlikely(dma_mapping_error(sq->pdev, dma_addr)))
L181: 			goto dma_unmap_wqe_err;
L182: 		dseg->addr       = cpu_to_be64(dma_addr);
L183: 		dseg->lkey       = sq->mkey_be;
L184: 		dseg->byte_count = cpu_to_be32(headlen);
L185: 
L186: 		mlx5e_dma_push(sq, dma_addr, headlen, MLX5E_DMA_MAP_SINGLE);
L187: 		num_dma++;
L188: 		dseg++;
L189: 	}
L190: 
L191: 	for (i = 0; i < skb_shinfo(skb)->nr_frags; i++) {
L192: 		skb_frag_t *frag = &skb_shinfo(skb)->frags[i];
L193: 		int fsz = skb_frag_size(frag);
L194: 
L195: 		dma_addr = skb_frag_dma_map(sq->pdev, frag, 0, fsz,
L196: 					    DMA_TO_DEVICE);
L197: 		if (unlikely(dma_mapping_error(sq->pdev, dma_addr)))
L198: 			goto dma_unmap_wqe_err;
L199: 		dseg->addr       = cpu_to_be64(dma_addr);
L200: 		dseg->lkey       = sq->mkey_be;
L201: 		dseg->byte_count = cpu_to_be32(fsz);
L202: 
L203: 		mlx5e_dma_push(sq, dma_addr, fsz, MLX5E_DMA_MAP_PAGE);
L204: 		num_dma++;
L205: 		dseg++;
L206: 	}
L207: 
L208: 	return num_dma;
L209: 
L210: dma_unmap_wqe_err:
L211: 	mlx5e_dma_unmap_wqe_err(sq, num_dma);
L212: 	return -ENOMEM;
L213: }
