L250: static void mlx5e_sq_xmit_prepare(struct mlx5e_txqsq *sq, struct sk_buff *skb,
L251: 				  struct mlx5e_accel_tx_state *accel,
L252: 				  struct mlx5e_tx_attr *attr)
L253: {
L254: 	struct mlx5e_sq_stats *stats = sq->stats;
L255: 	if (skb_is_gso(skb)) {
L256: 		int hopbyhop;
L257: 		u16 ihs = mlx5e_tx_get_gso_ihs(sq, skb, &hopbyhop);
L258: 
L259: 		*attr = (struct mlx5e_tx_attr) {
L260: 			.opcode    = MLX5_OPCODE_LSO,
L261: 			.mss       = cpu_to_be16(skb_shinfo(skb)->gso_size),
L262: 			.ihs       = ihs,
L263: 			.num_bytes = skb->len + (skb_shinfo(skb)->gso_segs - 1) * ihs,
L264: 			.headlen   = skb_headlen(skb) - ihs - hopbyhop,
L265: 			.hopbyhop  = hopbyhop,
L266: 		};
L267: 		stats->packets += skb_shinfo(skb)->gso_segs;
L268: 	} else {
L269: 		u8 mode = mlx5e_tx_wqe_inline_mode(sq, skb, accel);
L270: 		u16 ihs = mlx5e_calc_min_inline(mode, skb);
L271: 
L272: 		*attr = (struct mlx5e_tx_attr) {
L273: 			.opcode    = MLX5_OPCODE_SEND,
L274: 			.mss       = cpu_to_be16(0),
L275: 			.ihs       = ihs,
L276: 			.num_bytes = max_t(unsigned int, skb->len, ETH_ZLEN),
L277: 			.headlen   = skb_headlen(skb) - ihs,
L278: 		};
L279: 
L280: 		stats->packets++;
L281: 	}
L282: 
L283: 	attr->insz = mlx5e_accel_tx_ids_len(sq, accel);
L284: 	stats->bytes += attr->num_bytes;
L285: }
L286: static void mlx5e_sq_calc_wqe_attr(struct sk_buff *skb, const struct mlx5e_tx_attr *attr,
L287: 				   struct mlx5e_tx_wqe_attr *wqe_attr)
L288: {
L289: 	u16 ds_cnt = MLX5E_TX_WQE_EMPTY_DS_COUNT;
L290: 	u16 ds_cnt_inl = 0;
L291: 	u16 ds_cnt_ids = 0;
L292: 
L293: 	/* Sync the calculation with MLX5E_MAX_TX_WQEBBS. */
L294: 
L295: 	if (attr->insz)
L296: 		ds_cnt_ids = DIV_ROUND_UP(sizeof(struct mlx5_wqe_inline_seg) + attr->insz,
L297: 					  MLX5_SEND_WQE_DS);
L298: 	ds_cnt += !!attr->headlen + skb_shinfo(skb)->nr_frags + ds_cnt_ids;
L299: 	if (attr->ihs) {
L300: 		u16 inl = attr->ihs - INL_HDR_START_SZ;
L301: 
L302: 		if (skb_vlan_tag_present(skb))
L303: 			inl += VLAN_HLEN;
L304: 
L305: 		ds_cnt_inl = DIV_ROUND_UP(inl, MLX5_SEND_WQE_DS);
L306: 		if (WARN_ON_ONCE(ds_cnt_inl > MLX5E_MAX_TX_INLINE_DS))
L307: 			netdev_warn(skb->dev, "ds_cnt_inl = %u > max %u\n", ds_cnt_inl,
L308: 				    (u16)MLX5E_MAX_TX_INLINE_DS);
L309: 		ds_cnt += ds_cnt_inl;
L310: 	}
L311: 	*wqe_attr = (struct mlx5e_tx_wqe_attr) {
L312: 		.ds_cnt     = ds_cnt,
L313: 		.ds_cnt_inl = ds_cnt_inl,
L314: 		.ds_cnt_ids = ds_cnt_ids,
L315: 		.num_wqebbs = DIV_ROUND_UP(ds_cnt, MLX5_SEND_WQEBB_NUM_DS),
L316: 	};
L317: }
