L350: static inline void
L351: mlx5e_txwqe_complete(struct mlx5e_txqsq *sq, struct sk_buff *skb,
L352: 		     const struct mlx5e_tx_attr *attr,
L353: 		     const struct mlx5e_tx_wqe_attr *wqe_attr, u8 num_dma,
L354: 		     struct mlx5e_tx_wqe_info *wi, struct mlx5_wqe_ctrl_seg *cseg,
L355: 		     struct mlx5_wqe_eth_seg *eseg, bool xmit_more)
L356: {
L357: 	struct mlx5_wq_cyc *wq = &sq->wq;
L358: 	bool send_doorbell;
L359: 	*wi = (struct mlx5e_tx_wqe_info) {
L360: 		.skb = skb,
L361: 		.num_bytes = attr->num_bytes,
L362: 		.num_dma = num_dma,
L363: 		.num_wqebbs = wqe_attr->num_wqebbs,
L364: 		.num_fifo_pkts = 0,
L365: 	};
L366: 
L367: 	cseg->opmod_idx_opcode = cpu_to_be32((sq->pc << 8) | attr->opcode);
L368: 	cseg->qpn_ds           = cpu_to_be32((sq->sqn << 8) | wqe_attr->ds_cnt);
L369: 
L370: 	mlx5e_tx_skb_update_hwts_flags(skb);
L371: 
L372: 	sq->pc += wi->num_wqebbs;
L373: 
L374: 	mlx5e_tx_check_stop(sq);
L375: 	if (unlikely(sq->ptpsq &&
L376: 		     (skb_shinfo(skb)->tx_flags & SKBTX_HW_TSTAMP))) {
L377: 		u8 metadata_index = be32_to_cpu(eseg->flow_table_metadata);
L378: 
L379: 		mlx5e_ptp_metadata_fifo_pop(&sq->ptpsq->metadata_freelist);
L380: 		mlx5e_skb_cb_hwtstamp_init(skb);
L381: 		mlx5e_ptp_metadata_map_put(&sq->ptpsq->metadata_map, skb,
L382: 					   metadata_index);
L383: 		/* ensure skb is put on metadata_map before tracking the index */
L384: 		wmb();
L385: 		mlx5e_ptpsq_track_metadata(sq->ptpsq, metadata_index);
L386: 		if (!netif_tx_queue_stopped(sq->txq) &&
L387: 		    mlx5e_ptpsq_metadata_freelist_empty(sq->ptpsq)) {
L388: 			netif_tx_stop_queue(sq->txq);
L389: 			sq->stats->stopped++;
L390: 		}
L391: 		skb_get(skb);
L392: 	}
L393: 	send_doorbell = __netdev_tx_sent_queue(sq->txq, attr->num_bytes, xmit_more);
L394: 	if (send_doorbell)
L395: 		mlx5e_notify_hw(wq, sq->pc, sq->uar_map, cseg);
L396: }
L397: static void
L398: mlx5e_sq_xmit_wqe(struct mlx5e_txqsq *sq, struct sk_buff *skb,
L399: 		  const struct mlx5e_tx_attr *attr, const struct mlx5e_tx_wqe_attr *wqe_attr,
L400: 		  struct mlx5e_tx_wqe *wqe, u16 pi, bool xmit_more)
L401: {
L402: 	struct mlx5_wqe_ctrl_seg *cseg;
L403: 	struct mlx5_wqe_eth_seg  *eseg;
L404: 	struct mlx5_wqe_data_seg *dseg;
L405: 	struct mlx5e_tx_wqe_info *wi;
L406: 	u16 ihs = attr->ihs;
L407: 	struct ipv6hdr *h6;
L408: 	struct mlx5e_sq_stats *stats = sq->stats;
L409: 	int num_dma;
L410: 
L411: 	stats->xmit_more += xmit_more;
L412: 	/* fill wqe */
L413: 	wi   = &sq->db.wqe_info[pi];
L414: 	cseg = &wqe->ctrl;
L415: 	eseg = &wqe->eth;
L416: 	dseg =  wqe->data;
L417: 
L418: 	eseg->mss = attr->mss;
L419: 
L420: 	if (ihs) {
L421: 		u8 *start = eseg->inline_hdr.start;
L422: 		if (unlikely(attr->hopbyhop)) {
L423: 			/* remove the HBH header.
L424: 			 * Layout: [Ethernet header][IPv6 header][HBH][TCP header]
L425: 			 */
L426: 			if (skb_vlan_tag_present(skb)) {
L427: 				mlx5e_insert_vlan(start, skb, ETH_HLEN + sizeof(*h6));
L428: 				ihs += VLAN_HLEN;
L429: 				h6 = (struct ipv6hdr *)(start + sizeof(struct vlan_ethhdr));
L430: 			} else {
L431: 				unsafe_memcpy(start, skb->data,
L432: 					      ETH_HLEN + sizeof(*h6),
L433: 					      MLX5_UNSAFE_MEMCPY_DISCLAIMER);
L434: 				h6 = (struct ipv6hdr *)(start + ETH_HLEN);
L435: 			}
L436: 			h6->nexthdr = IPPROTO_TCP;
L437: 			/* Copy the TCP header after the IPv6 one */
L438: 			memcpy(h6 + 1,
L439: 			       skb->data + ETH_HLEN + sizeof(*h6) +
L440: 					sizeof(struct hop_jumbo_hdr),
L441: 			       tcp_hdrlen(skb));
L442: 			/* Leave ipv6 payload_len set to 0, as LSO v2 specs request. */
L443: 		} else if (skb_vlan_tag_present(skb)) {
L444: 			mlx5e_insert_vlan(start, skb, ihs);
L445: 			ihs += VLAN_HLEN;
L446: 			stats->added_vlan_packets++;
L447: 		} else {
L448: 			unsafe_memcpy(eseg->inline_hdr.start, skb->data,
L449: 				      attr->ihs,
L450: 				      MLX5_UNSAFE_MEMCPY_DISCLAIMER);
L451: 		}
L452: 		eseg->inline_hdr.sz |= cpu_to_be16(ihs);
L453: 		dseg += wqe_attr->ds_cnt_inl;
L454: 	} else if (skb_vlan_tag_present(skb)) {
L455: 		eseg->insert.type = cpu_to_be16(MLX5_ETH_WQE_INSERT_VLAN);
L456: 		if (skb->vlan_proto == cpu_to_be16(ETH_P_8021AD))
L457: 			eseg->insert.type |= cpu_to_be16(MLX5_ETH_WQE_SVLAN);
L458: 		eseg->insert.vlan_tci = cpu_to_be16(skb_vlan_tag_get(skb));
L459: 		stats->added_vlan_packets++;
L460: 	}
L461: 	dseg += wqe_attr->ds_cnt_ids;
L462: 	num_dma = mlx5e_txwqe_build_dsegs(sq, skb, skb->data + attr->ihs + attr->hopbyhop,
L463: 					  attr->headlen, dseg);
L464: 	if (unlikely(num_dma < 0))
L465: 		goto err_drop;
L466: 
L467: 	mlx5e_txwqe_complete(sq, skb, attr, wqe_attr, num_dma, wi, cseg, eseg, xmit_more);
L468: 
L469: 	return;
L470: 
L471: err_drop:
L472: 	stats->dropped++;
L473: 	dev_kfree_skb_any(skb);
L474: 	mlx5e_tx_flush(sq);
L475: }
L476: static bool mlx5e_tx_skb_supports_mpwqe(struct sk_buff *skb, struct mlx5e_tx_attr *attr)
L477: {
L478: 	return !skb_is_nonlinear(skb) && !skb_vlan_tag_present(skb) && !attr->ihs &&
L479: 	       !attr->insz && !mlx5e_macsec_skb_is_offload(skb);
L480: }
