L482: static bool mlx5e_tx_mpwqe_same_eseg(struct mlx5e_txqsq *sq, struct mlx5_wqe_eth_seg *eseg)
L483: {
L484: 	struct mlx5e_tx_mpwqe *session = &sq->mpwqe;
L485: 	/* Assumes the session is already running and has at least one packet. */
L486: 	return !memcmp(&session->wqe->eth, eseg, MLX5E_ACCEL_ESEG_LEN);
