L498: 	net_prefetchw(wqe->data);
L499: 	*session = (struct mlx5e_tx_mpwqe) {
L500: 		.wqe = wqe,
L501: 		.bytes_count = 0,
L502: 		.ds_count = MLX5E_TX_WQE_EMPTY_DS_COUNT,
L503: 		.pkt_count = 0,
L504: 		.inline_on = 0,
L505: 	};
L506: 
L507: 	memcpy(&session->wqe->eth, eseg, MLX5E_ACCEL_ESEG_LEN);
