L517: static void mlx5e_tx_mpwqe_add_dseg(struct mlx5e_txqsq *sq, struct mlx5e_xmit_data *txd)
L518: {
L519: 	struct mlx5e_tx_mpwqe *session = &sq->mpwqe;
L520: 	struct mlx5_wqe_data_seg *dseg;
L521: 	dseg = (struct mlx5_wqe_data_seg *)session->wqe + session->ds_count;
L522: 
L523: 	session->pkt_count++;
L524: 	session->bytes_count += txd->len;
L525: 
L526: 	dseg->addr = cpu_to_be64(txd->dma_addr);
L527: 	dseg->byte_count = cpu_to_be32(txd->len);
L528: 	dseg->lkey = sq->mkey_be;
L529: 	session->ds_count++;
L530: 
L531: 	sq->stats->mpwqe_pkts++;
L532: }
L533: static struct mlx5_wqe_ctrl_seg *mlx5e_tx_mpwqe_session_complete(struct mlx5e_txqsq *sq)
L534: {
L535: 	struct mlx5e_tx_mpwqe *session = &sq->mpwqe;
L536: 	u8 ds_count = session->ds_count;
L537: 	struct mlx5_wqe_ctrl_seg *cseg;
L538: 	struct mlx5e_tx_wqe_info *wi;
L539: 	u16 pi;
L540: 
L541: 	cseg = &session->wqe->ctrl;
L542: 	cseg->opmod_idx_opcode = cpu_to_be32((sq->pc << 8) | MLX5_OPCODE_ENHANCED_MPSW);
L543: 	cseg->qpn_ds = cpu_to_be32((sq->sqn << 8) | ds_count);
L544: 	pi = mlx5_wq_cyc_ctr2ix(&sq->wq, sq->pc);
L545: 	wi = &sq->db.wqe_info[pi];
L546: 	*wi = (struct mlx5e_tx_wqe_info) {
L547: 		.skb = NULL,
L548: 		.num_bytes = session->bytes_count,
L549: 		.num_wqebbs = DIV_ROUND_UP(ds_count, MLX5_SEND_WQEBB_NUM_DS),
L550: 		.num_dma = session->pkt_count,
L551: 		.num_fifo_pkts = session->pkt_count,
L552: 	};
L553: 
L554: 	sq->pc += wi->num_wqebbs;
L555: 
L556: 	session->wqe = NULL;
L557: 
L558: 	mlx5e_tx_check_stop(sq);
L559: 
L560: 	return cseg;
L561: }
L562: static void
L563: mlx5e_sq_xmit_mpwqe(struct mlx5e_txqsq *sq, struct sk_buff *skb,
L564: 		    struct mlx5_wqe_eth_seg *eseg, bool xmit_more)
